function pb.model(Jr,Kr,Lr)
local Mr=tostring(Jr)..upe[2184]..tostring(Lr and Lr.atk)..upe[2184]..tostring(Lr and Lr.cd)
local Nr=pb._model[Mr]
if Nr~=nil then
return Nr or nil
end
local Or,Pr={},false
local Qr=math.max(0.3,tonumber(Lr and Lr.cd)or 2)
local Rr=math.min(1,(tonumber(Kr and Kr.n)or 1)/4)
local Sr,Tr=pcall(pb.guess,Jr)
local Ur,Vr={},{}
for Wr,Xr in ipairs(Sr and type(Tr)==upe[2059]and Tr or{})do
if Xr.hand then
Ur[Xr.pid]=true
end
Vr[Xr.pid]=Xr.nums
end
for Yr,Zr in pairs(pb.rules(Jr))do
if not Ur[Yr]then
local as={}
for bs,cs in pairs(type(Vr[Yr])==upe[2059]and Vr[Yr]or{})do
as[bs]=cs
end
for ds,es in pairs(type(Zr.nums)==upe[2059]and Zr.nums or{})do
as[ds]=es
end
local fs=Zr.trigger~=nil and tostring(Zr.trigger):find(upe[2464],1,true)~=nil
if Zr.family==upe[2243]then
local gs=(fs and pb.ABILITY_UPTIME or 1)*(Zr.who==upe[2312]and pb.RANGE_SHARE or 1)
local hs=Or.aura or{typed={}}
for js,ks in pairs(type(as.typed)==upe[2059]and as.typed or{})do
hs.typed[js]=math.max(hs.typed[js]or 0,(tonumber(ks)or 0)*gs)
end
local ls=tonumber(as.dmgMax)or tonumber(as.dmg)
if ls then
hs.dmg=math.max(hs.dmg or 0,ls*gs)
end
if as.crit then
hs.crit=math.max(hs.crit or 0,(tonumber(as.crit)or 0)*gs)
end
Or.aura,Pr=hs,true
elseif Zr.family==upe[2240]then
local ms=pb.KW[tostring(Zr.keyword or upe[978])]
local ns=tonumber(as.chance)or 1
local ps=tonumber(as.secsSeen)or tonumber(as.secs)or 5
local qs=as.keep or as.keepSeen
local rs=qs and math.min(1,ns*4)or math.min(1,ps*ns/Qr)
if fs then
rs=math.min(rs,ps/60)
end
if ms and ms.kind==upe[2230]and not(type(as.shred)==upe[2059])then
local ss=tonumber(as.amp)
local ts=Kr and((type(Kr.ampTypes)==upe[2059]and Kr.ampTypes[ms.dtype])or(tonumber(Kr.amp)or 0)>0)
if ss and ss>0 and not ts then
Or.fx,Pr=(Or.fx or 0)+ss*V.TYPED_AMP_SHARE*rs*Rr,true
end
elseif ms and(ms.kind==upe[2177]or ms.kind==upe[2238])then
if not(Kr and((tonumber(Kr.stun)or 0)>0 or(tonumber(Kr.slowTime)or 0)>0))then
Or.stun=(ms.kind==upe[2238]and 0.5 or 1)*ps
if as.slow then
Or.slowP,Or.slowT=tonumber(as.slow),ps
end
Pr=true
end
elseif ms and ms.kind==upe[2179]then
if not(Kr and(tonumber(Kr.slowTime)or 0)>0)then
Or.slowP,Or.slowT,Pr=tonumber(as.slow)or tonumber(as.slowSeen)or 0.3,ps,true
end
elseif ms and ms.kind==upe[2237]then
local us=tonumber(as.dot)or 0
if us>0 and(tonumber(Kr and Kr.dot)or 0)<us*0.5 then
local vs=math.min(1.5,us)*ns
Or.dot,Pr=(Or.dot or 0)+vs,true
if tostring(Zr.keyword)==upe[1901]then
Or.burnDot=(Or.burnDot or 0)+vs
end
end
end
if type(as.ampFrom)==upe[2059]and tostring(as.ampFrom.kind)==upe[1901]and(tonumber(as.ampFrom.amp)or 0)>0 then
local ws=(type(as.secsBy)==upe[2059]and#as.secsBy>0)and as.secsBy or{tonumber(as.secsSeen)or tonumber(as.secs)or 5}
Or.flames,Pr={amp=tonumber(as.ampFrom.amp),secs=ws},true
end
elseif Zr.family==upe[2298]then
Or.exec,Pr=tonumber(as.below)or 0.25,true
end
end
end
pb._model[Mr]=Pr and Or or false
return Pr and Or or nil
end
