table.insert(lbb,{kind=upe[3091],uuid=sbb,name=vbb,gain=Abb,add=xbb,planned=Bbb.planned,items=Bbb.n,lvl0=Cbb,lvl1=kb.level({unit_id=ubb,xp=(tonumber(tbb.xp)or 0)+(Bbb.planned>0 and Bbb.planned or xbb)}),text=string.format(upe[3092],vbb,U.fmt(xbb),Dbb>Cbb and string.format(upe[3093],Cbb,Dbb)or string.format(upe[3094],Cbb),Abb)})
end
end
end
end
table.sort(lbb,function(Ebb,Fbb)
if Ebb.gain~=Fbb.gain then
return Ebb.gain>Fbb.gain
end
return Ebb.text<Fbb.text
end)
for Gbb in pairs(V._mult)do
