end
function kb.xpRate()
local Jbb=N.session()
if not Jbb then
return 0
end
local Kbb=0
for Lbb,Mbb in ipairs(kb.core())do
local Nbb=Jbb.collection:get_unit_by_uuid(Mbb)
if Nbb then
local Obb,Pbb=kb.gainXp(Nbb,500000)
if Pbb>0 then
Kbb=math.max(Kbb,Obb/Pbb)
end
end
end
local Qbb=Kbb*(O.strengthValue or 300)
if(tonumber(N.cur(upe[2126]))or 0)>(O.xpGoldFloor or 100000)then
Qbb=math.min(Qbb,(N.GOLD_VALUE or 0.02)/14)
end
return Qbb
end
function kb.xpGuess(Rbb)
local Sbb=Rbb.level and N.Levels[Rbb.level]
if not Sbb then
return 0
end
local Tbb=math.min(9,tonumber(Sbb.story_world_rank)or tonumber(Rbb.rank)or 9)
local Ubb=tonumber(Sbb.story_level_rank)or 6
local Vbb=(Rbb.kind==upe[2100]and 1.5 or 1)*(Tbb>5 and 2 or 1)
local Wbb=2.1564^(Tbb-1)*(40+10*Ubb)/Vbb
if Rbb.kind==upe[2079]then
Wbb=3*30*2.1564^(Tbb-1)/Vbb
end
local Xbb=Tbb>=9 and 0.3 or(Tbb>=7 and 0.5 or 1)
return Wbb*Xbb*6
end
function kb.modeBonus(Ybb)
if not(O.team and O.teamXp)or Ybb.kind==upe[2080]or Ybb.kind==upe[2077]then
return 0
end
local Zbb=kb._xpRate and os.time()-(kb._xpRateAt or 0)<300 and kb._xpRate or nil
if not Zbb then
Zbb=kb.xpRate()
kb._xpRate,kb._xpRateAt=Zbb,os.time()
end
if Zbb<=0 then
return 0
end
local _bb=P.modes and P.modes[Ybb.key]
local acb=tonumber(_bb and _bb.xp)or kb.xpGuess(Ybb)
local bcb=acb*Zbb
if bcb<1 then
return 0
end
return bcb,string.format(upe[3095],U.fmt(acb),math.floor(bcb+0.5))
end
function kb.xpSettle()
local ccb=P.lastRun
if not(ccb and type(ccb.xp0)==upe[2059]and ccb.key)then
return
end
local dcb=N.session()
if not dcb then
return
end
local ecb,fcb=0,0
for gcb,hcb in pairs(ccb.xp0)do
local icb=dcb.collection:get_unit_by_uuid(gcb)
if icb then
ecb=ecb+math.max(0,(tonumber(icb.xp)or 0)-(tonumber(hcb)or 0))
fcb=fcb+1
end
end
P.lastRun=nil
if fcb==0 then
return
end
local jcb=W.rec(ccb.key)
jcb.xp=jcb.xp and(jcb.xp+(ecb-jcb.xp)*0.3)or ecb
if ecb>0 then
F.log(2,kb.LOG,string.format(upe[3096],ccb.key,U.fmt(ecb)))
end
F.saveSoon()
