function kb.feedPlan(lcb)
local mcb=V.trait(lcb)
local ncb=mcb==upe[3097]and 1.5 or 1
local ocb=math.max(0,kb.xpFor(lcb.unit_id,kb.cap(lcb))-(tonumber(lcb.xp)or 0))
local pcb,qcb,rcb={},0,0
for scb,tcb in ipairs(kb.foodHeld())do
local ucb=tcb.xp*ncb
local vcb=math.min(tcb.n,math.floor((ocb-qcb)/math.max(1,ucb)))
if vcb>0 then
pcb[tcb.id]=vcb
qcb=qcb+vcb*ucb
rcb=rcb+vcb
end
end
return{feed=pcb,planned=qcb,n=rcb}
end
function kb.run(wcb)
local xcb=N.session()
local ycb=xcb and xcb.collection:get_unit_by_uuid(wcb.uuid)
if not ycb then
return
end
if wcb.kind==upe[3091]then
local zcb=kb.feedPlan(ycb)
local Acb,Bcb,Ccb=zcb.feed,zcb.planned,zcb.n
if Ccb==0 then
P.str.feedNote=wcb.name..upe[3098]
return
end
local Dcb,Ecb=tonumber(ycb.xp)or 0,kb.level(ycb)
local Fcb,Gcb=F.request(upe[3091],upe[3099],wcb.uuid,Acb)
local Hcb=U.now()
while U.now()-Hcb<4 and(tonumber((xcb.collection:get_unit_by_uuid(wcb.uuid)or ycb).xp)or 0)<=Dcb do
task.wait(0.25)
end
local Icb=xcb.collection:get_unit_by_uuid(wcb.uuid)or ycb
local Jcb=(tonumber(Icb.xp)or 0)-Dcb
if Jcb>0 then
local Kcb=kb.level(Icb)
local Lcb=Kcb>Ecb and string.format(upe[3093],Ecb,Kcb)or string.format(upe[3094],Ecb)
cb.add(string.format(upe[3100],Ccb,wcb.name),Ccb,upe[3101],string.format(upe[3102],U.fmt(Jcb),Lcb))
kb.note(string.format(upe[3103],wcb.name,Ccb,U.fmt(Jcb),Lcb,math.abs(Jcb-Bcb)>Bcb*0.1 and string.format(upe[3104],U.fmt(Bcb))or upe[978]))
else
kb.note(string.format(upe[3105],wcb.name,tostring(Fcb and Gcb or upe[2594])))
F.backoff(upe[3091],600)
end
end
end
