local YLb=0
pcall(function()
YLb=ULb.inventory:get_number_of_owned_item(WLb)
end)
if(tonumber(YLb)or 0)>0 then
VLb=math.max(VLb,tonumber(XLb)or 0)
end
end
return VLb>0 and VLb or nil
end
function gb.unitBonus(ZLb,_Lb)
