for AMb=1,zMb do
local BMb=gb.enemy(eMb,yMb.k,fMb)
if BMb then
table.insert(hMb,BMb)
end
end
wMb=wMb+zMb
end
local CMb=eMb.ld._infinite_bound_level and fMb==eMb.total
if CMb then
local DMb,EMb={},0
for FMb,GMb in pairs(eMb.configs)do
if type(GMb)==upe[2059]and tonumber(GMb.spawn_tier_boss)and(BHb(N.LU.Infinite.infinite_get_boss_unit_chance,GMb,fMb)or 0)>0 then
local HMb=gb.baseStats(eMb,FMb)
if HMb then
table.insert(DMb,{k=FMb,hp=HMb,tier=tonumber(GMb.spawn_tier_boss)})
EMb=EMb+HMb
end
end
end
table.sort(DMb,function(IMb,JMb)
return IMb.tier>JMb.tier
end)
local KMb=type(eMb.ld._dungeon)==upe[2059]and(tonumber(eMb.ld._dungeon.depth)or 0)>=20
local LMb=DMb[1]
if LMb and not KMb then
local MMb=EMb/ #DMb
for NMb,OMb in ipairs(DMb)do
if math.abs(OMb.hp-MMb)<math.abs(LMb.hp-MMb)then
LMb=OMb
end
end
end
if LMb then
local PMb=gb.enemy(eMb,LMb.k,fMb)
if PMb then
PMb.boss=true
table.insert(hMb,PMb)
end
end
elseif fMb%eMb.bossEvery==0 and not eMb.skip[tostring(fMb)]then
local QMb=math.max(1,math.min(6,math.floor(fMb/eMb.bossEvery)))
for RMb,SMb in pairs(eMb.configs)do
if type(SMb)==upe[2059]and tonumber(SMb.spawn_tier_boss)==QMb then
local TMb=gb.enemy(eMb,RMb,fMb)
if TMb then
TMb.boss=true
table.insert(hMb,TMb)
