function gb.footMove1()
local yQb={}
local function zQb(AQb)
if yQb[AQb]==nil then
local BQb,CQb=0,0
local DQb=P.learn[AQb]
if DQb and tonumber(DQb.n)and DQb.n>=1 then
local EQb=tonumber(DQb.eff)or 1
