local Eic=jb.roomValue(Dic,sic)
local Fic,Gic
for Hic,Iic in ipairs(jb.after(pic,Dic.choice))do
local Jic=jb.roomValue(Iic,sic)
if not Fic or Jic>Fic then
Fic,Gic=Jic,Iic
end
end
local Kic,Lic=jb.winP(Dic)
local Mic=Lic~=nil and Lic.won==false
local Nic=ric>=3 and 1 or(ric==2 and 2 or 6)
local Oic=1-(1-Kic)^math.max(1,ric)
Dic.oldScore=Oic*(Eic+0.6*(Fic or 0))-(1-Kic)*Nic
