if Pic and not Qic then
Dic.blocked=Ric
end
if not Dic.blocked then
if not yic or Dic.score>yic.score then
yic=Dic
end
if Mic then
if not Bic or Dic.score>Bic.score then
Bic=Dic
end
elseif not Aic or Dic.score>Aic.score then
Aic=Dic
end
end
if not zic or Dic.score>zic.score then
zic=Dic
end
end
if yic and yic.simLost and Aic then
F.log(1,upe[3983],string.format(upe[3984],jb.roomName(yic),tostring(yic.sim and yic.sim.margin or upe[2295]),math.floor((1-jb.lossWin())*100+0.5),jb.roomName(Aic)))
