F.log(1,upe[3983],string.format(upe[3985],jb.roomName(Bic),tostring(Bic.sim and Bic.sim.margin or upe[2295]),jb.roomName(yic)))
end
yic=yic or zic
jb._pick={sig=xic,x=yic,rooms=tic}
