if Tkc+Ukc<=0 or Okc>=2 then
break
end
local Vkc,Wkc
if Tkc>0 then
Vkc,Wkc=F.request(upe[4021],upe[4022])
else
Vkc,Wkc=F.request(upe[4021],upe[4022],true)
end
if Vkc and Wkc~=nil then
