table.insert(P.dg.pay,{at=os.time(),rare=clc<Ukc,gems=dlc.gems-Qkc.gems,luck=jb.luck(Fkc),paid=elc,items=flc})
while#P.dg.pay>60 do
table.remove(P.dg.pay,1)
end
Qkc=dlc
end
end
jb.note(string.format(upe[4025],Mkc,Nkc,Gkc and upe[4026]or(Kkc<=1 and upe[4027]or upe[4028]),jb.luck(Fkc),(tonumber(N.cur(upe[2124]))or 0)-Pkc))
local ilc,jlc,klc=jb.res(jb.data())
if(Gkc or Lkc>=jb.ROOMS)and jlc+klc>0 then
