function bb.buildPath()
bb.samples={}
local ppc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not ppc then
return
end
for qpc,rpc in pairs(ppc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[qpc.Name])then
local spc={}
for tpc,upc in ipairs(rpc.points or{})do
table.insert(spc,upc.part.Position)
end
local vpc=0
for wpc=2,#spc do
vpc=vpc+(spc[wpc]-spc[wpc-1]).Magnitude
end
local xpc=0
for ypc=2,#spc do
local zpc,Apc=spc[ypc-1],spc[ypc]
local Bpc=(Apc-zpc).Magnitude
local Cpc=math.max(1,math.floor(Bpc/2))
for Dpc=0,Cpc-1 do
local Epc=zpc:Lerp(Apc,Dpc/Cpc)
table.insert(bb.samples,{pos=Epc,prog=(xpc+Bpc*Dpc/Cpc)/math.max(1,vpc),lane=qpc.Name})
end
xpc=xpc+Bpc
end
if spc[#spc]then
table.insert(bb.samples,{pos=spc[#spc],prog=1,lane=qpc.Name})
end
end
end
pcall(bb.readHidden,ppc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local Fpc=tonumber(bb.ld and bb.ld._portal_lanes)
local Gpc=gb.laneList(bb.samples)
if Fpc and Fpc>=1 and Gpc and#Gpc>Fpc then
bb.laneWant=Fpc
end
bb.laneTotal=Gpc and#Gpc or 1
bb.countLanes()
end
function bb.readHidden(Hpc)
local Ipc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(Ipc)~=upe[2059]or not next(Ipc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local Jpc
for Kpc,Lpc in pairs(Hpc)do
if Ipc[Kpc.Name]and type(Lpc.points)==upe[2059]and#Lpc.points>=2 then
local Mpc={}
for Npc,Opc in ipairs(Lpc.points)do
Mpc[Npc]=U.flat(Opc.part.Position)
end
local Ppc={}
for Qpc,Rpc in ipairs(bb.samples)do
local Spc=tostring(Rpc.lane)
Ppc[Spc]=Ppc[Spc]or{}
table.insert(Ppc[Spc],Rpc)
end
local Tpc,Upc
for Vpc,Wpc in pairs(Ppc)do
local Xpc=0
for Ypc=1,#Mpc,math.max(1,math.floor(#Mpc/20))do
local Zpc=math.huge
for _pc,aqc in ipairs(Wpc)do
local bqc=(U.flat(aqc.pos)-Mpc[Ypc]).Magnitude
if bqc<Zpc then
Zpc=bqc
end
end
Xpc=Xpc+Zpc
end
if not Upc or Xpc<Upc then
Tpc,Upc=Vpc,Xpc
end
end
local cqc,dqc,eqc,fqc,gqc,hqc={},nil,nil,nil,0,0
for iqc,jqc in ipairs(Mpc)do
local kqc,lqc=nil,math.huge
for mqc,nqc in ipairs(Ppc[Tpc])do
local oqc=(U.flat(nqc.pos)-jqc).Magnitude
if oqc<lqc then
lqc,kqc=oqc,nqc.prog
end
end
hqc=math.max(hqc,lqc)
if eqc then
local pqc=kqc-eqc
local qqc=(pqc>0.002 and 1)or(pqc< -0.002 and-1)or fqc
if fqc and qqc and qqc~=fqc then
table.insert(cqc,math.floor(eqc*1000+0.5)/1000)
end
fqc,gqc=qqc or fqc,gqc+math.abs(pqc)
else
dqc=kqc
end
eqc=kqc
if iqc%50==0 then
task.wait()
end
end
if eqc and hqc<=8 then
table.insert(cqc,math.floor(eqc*1000+0.5)/1000)
Jpc=Jpc or{}
Jpc[Kpc.Name]={from=math.floor((dqc or 0)*1000+0.5)/1000,len=math.floor(gqc*1000+0.5)/1000,turns=cqc,road=Tpc}
end
end
end
if not Jpc then
return
end
local rqc=bb.ld.map
P.maps[rqc]=P.maps[rqc]or{}
local sqc=P.maps[rqc].hidden
P.maps[rqc].hidden=Jpc
if type(sqc)~=upe[2059]then
for tqc,uqc in pairs(Jpc)do
F.log(1,upe[2728],string.format(upe[4118],tqc,uqc.len,tostring(uqc.road),math.floor((#uqc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
