function bb.valid(Ctc,Dtc,Etc)
local Ftc=N.PC.raycast(Ctc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not Ftc then
return nil
end
if not N.PC.is_valid_raycast_hit(Ftc.Instance,Dtc)then
return nil
end
local Gtc=Ftc.Position
if bb.blockedSpot(Gtc)then
return nil
end
local Htc=(tonumber(Dtc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(Htc*2,2.5,Htc*2)
bb.probe.CFrame=CFrame.new(Gtc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
local Itc=U.flat(Gtc)
local Jtc=bb.grifZone
if Jtc and type(Dtc)==upe[2059]and Dtc.id~=V.GRIF.egg and not V.sacFodder(Dtc.id)and(Itc-Jtc.p).Magnitude<=Jtc.r+1.5 then
return nil
end
for Ktc,Ltc in ipairs(bb.mine or{})do
local Mtc=Ltc:FindFirstChild(upe[4154])
local Ntc=Mtc and Mtc.Position or Ltc:GetPivot().Position
local Otc=Mtc and math.max(Mtc.Size.X,Mtc.Size.Z)/2 or 1.5
if(Itc-U.flat(Ntc)).Magnitude<Htc+Otc then
return nil
end
end
if not Etc then
for Ptc,Qtc in ipairs(bb.blockers())do
if(Itc-Qtc.p).Magnitude<Htc+Qtc.r then
return nil
end
end
end
return Gtc
end
function bb.buildCandidates()
bb.cands={}
local Rtc={}
for Stc=1,#bb.samples,3 do
local Ttc=bb.samples[Stc]
local Utc=bb.samples[math.min(#bb.samples,Stc+1)]
local Vtc=U.flat(Utc.pos-Ttc.pos)
if Vtc.Magnitude<0.01 then
Vtc=Vector3 .new(1,0,0)
end
Vtc=Vtc.Unit
local Wtc=Vector3 .new(-Vtc.Z,0,Vtc.X)
for Xtc,Ytc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for Ztc,_tc in ipairs({1,-1})do
local auc=Ttc.pos+Wtc*Ytc*_tc
local buc=string.format(upe[4151],math.floor(auc.X/1.5),math.floor(auc.Z/1.5))
if not Rtc[buc]then
Rtc[buc]=true
table.insert(bb.cands,auc)
end
end
end
end
end
function bb.coverage(cuc,duc)
local euc={}
for fuc,guc in ipairs(cuc)do
local huc=guc._stats
if not V.isFarm(huc.id.Value)and huc:FindFirstChild(upe[2312])then
table.insert(euc,{p=U.flat(guc:GetPivot().Position),r=huc.range.Value*(V.SUMMONER[huc.id.Value]and V.SUMMONER[huc.id.Value].reach or 1),air=bb.canAir(guc)})
end
end
local iuc,juc=0,0
if#euc>0 then
for kuc,luc in ipairs(bb.samples)do
if luc.prog>juc then
local muc=U.flat(luc.pos)
for nuc,ouc in ipairs(euc)do
if(muc-ouc.p).Magnitude<=ouc.r then
if luc.prog>iuc then
iuc=luc.prog
end
if ouc.air then
juc=luc.prog
break
end
end
end
end
end
end
local puc,quc={},bb.laneCount
if quc and quc.n>=2 and#euc>0 then
local ruc={}
for suc,tuc in ipairs(bb.samples)do
local uuc=U.flat(tuc.pos)
for vuc,wuc in ipairs(euc)do
if(uuc-wuc.p).Magnitude<=wuc.r then
local xuc=tostring(tuc.lane)
ruc[xuc]=(ruc[xuc]or 0)+1
if tuc.prog>(puc[xuc]or 0)then
puc[xuc]=tuc.prog
end
break
end
end
end
local yuc,zuc={},0
for Auc,Buc in pairs(quc.by)do
yuc[Auc]=(ruc[Auc]or 0)/math.max(1,Buc)
zuc=math.max(zuc,yuc[Auc])
end
bb.laneW={}
for Cuc,Duc in pairs(quc.by)do
bb.laneW[Cuc]=(quc.avg/math.max(1,Duc))*(1+1.5*(zuc>0 and(1-yuc[Cuc]/zuc)or 0))
end
bb.laneFrac=yuc
else
bb.laneW,bb.laneFrac=nil,nil
end
local Euc,Fuc,Guc
if#euc>0 then
for Huc,Iuc in ipairs(duc)do
local Juc=(bb.laneW and Iuc.lane)and(puc[tostring(Iuc.lane)]or 0)or iuc
if Iuc.hp>0 and Iuc.prog>Juc+0.02 and Iuc.prog>(Euc or 0)then
Euc,Guc=Iuc.prog,bb.laneW and Iuc.lane or nil
end
if Iuc.hp>0 and Iuc.fly and Iuc.prog>juc+0.02 then
Fuc=true
end
end
end
local Kuc= #euc>0 and(bb.pressure or 0)>=iuc-0.08
return{covEnd=iuc,airEnd=juc,leak=Euc,leakLane=Guc,covL=puc,airLeak=Fuc,push=Kuc,units= #euc}
end
function bb.needLastLine(Luc)
