return false
end
local Muc,Nuc=0,0
for Ouc,Puc in ipairs(bb.mine or{})do
local Quc=Puc._stats
if not V.isFarm(Quc.id.Value)and Quc:FindFirstChild(upe[2312])then
local Ruc,Suc=U.flat(Puc:GetPivot().Position),Quc.range.Value
for Tuc,Uuc in ipairs(bb.samples)do
if Uuc.prog>=0.85 and(U.flat(Uuc.pos)-Ruc).Magnitude<=Suc then
Muc=Muc+1
if bb.canAir(Puc)then
Nuc=Nuc+1
end
break
end
end
end
end
return Muc<2 or(Nuc<1 and bb.flyMode()and bb.cardAir(Luc.id))
end
bb.airCache=setmetatable({},{__mode=upe[2445]})
function bb.canAir(Vuc)
local Wuc=Vuc._stats:FindFirstChild(upe[2151])and Vuc._stats.upgrade.Value or 0
local Xuc=bb.airCache[Vuc]
if not Xuc or Xuc.lvl~=Wuc then
