V._airFrom={}
function V.airFrom(Zuc)
local _uc=V._airFrom[Zuc]
if _uc~=nil then
return _uc or nil
end
local avc=N.Units[Zuc]
if avc and(avc.hill_unit or avc.hybrid_placement or V.SUMMONER[Zuc])then
V._airFrom[Zuc]=0
return 0
end
local bvc=V.rows(Zuc)
if not(bvc and bvc.max)then
return bb.cardAir(Zuc)and 0 or nil
end
local cvc=false
for dvc=0,bvc.max do
local evc=bvc[dvc]and bvc[dvc].atk
if evc and N.Attacks[evc]and N.Attacks[evc].targets_flying then
cvc=dvc
break
end
end
if cvc==false and bb.cardAir(Zuc)then
cvc=0
end
V._airFrom[Zuc]=cvc
return cvc or nil
end
function bb.cardAir(fvc)
local gvc=N.Units[fvc]
if not gvc then
return false
end
if gvc.hill_unit or gvc.hybrid_placement then
return true
end
local hvc=V.field(fvc,upe[2165])or V.field(fvc,upe[2164])
return hvc and N.Attacks[hvc]and N.Attacks[hvc].targets_flying and true or false
end
function bb.airShare()
local ivc,jvc=0,0
for kvc,lvc in ipairs(bb.mine or{})do
local mvc=lvc._stats.id.Value
if not V.isFarm(mvc)then
local nvc,ovc=pcall(bb.liveDps,lvc,mvc)
ovc=nvc and ovc or 0
ivc=ivc+ovc
if bb.canAir(lvc)then
jvc=jvc+ovc
end
end
end
return ivc>0 and jvc/ivc or 0
end
