if Svc and Tvc and not Tvc.unsellable and not bb.sandSold[Pvc]and not V.idol(Rvc)and Qvc:FindFirstChild(upe[2312])and type(Svc.types)==upe[2059]and not bb.grifKeep(Pvc,Rvc)then
local Uvc,Vvc=U.flat(Pvc:GetPivot().Position),tonumber(Qvc.range.Value)or 0
local Wvc,Xvc=false,false
