local fwc=ewc and N.Units[ewc]
local gwc=dwc and dwc:FindFirstChild(upe[2436])and dwc.uuid.Value
if fwc and not fwc.unsellable and not bb.sandSold[ewc]and not V.isFarm(ewc)and not V.allyBuff(ewc)and not V.BLESS.by[ewc]and not V.idol(ewc)and dwc:FindFirstChild(upe[2312])and not bb.grifKeep(cwc,ewc)then
local hwc=tonumber(dwc.range.Value)or 0
for iwc,jwc in ipairs(bb.team or{})do
