end
end
if not lwc then
bb.sandSold[ewc]=true
local owc=dwc:FindFirstChild(upe[4160])and tonumber(dwc.total_spent.Value)or 0
local pwc,qwc=F.request(upe[2242],upe[2440],cwc)
if qwc==true then
