end
end
end
function bb.cover(rwc,swc,twc,uwc,vwc)
local wwc=0
local xwc=U.flat(rwc)
local ywc=twc and P.maps[bb.mapKey()]and P.maps[bb.mapKey()].dens
local zwc=bb.laneW
for Awc,Bwc in ipairs(vwc and bb.samples or bb.hurtSamples())do
if(U.flat(Bwc.pos)-xwc).Magnitude<=swc then
local Cwc=1
if ywc then
Cwc=0.15+0.85*(tonumber(ywc[math.min(gb.BINS,math.floor(Bwc.prog*gb.BINS)+1)])or 0)
end
if zwc then
Cwc=Cwc*(zwc[tostring(Bwc.lane)]or 1)
end
if uwc then
if uwc.leak and Bwc.prog>=uwc.leak-0.01 and(not uwc.leakLane or tostring(Bwc.lane)==uwc.leakLane)then
Cwc=Cwc+3
elseif uwc.push and Bwc.prog>uwc.covEnd then
Cwc=Cwc+0.6
end
end
wwc=wwc+Cwc
end
end
return wwc
end
