for _Kc,aLc in pairs(YKc)do
ZKc[_Kc]=aLc
end
return ZKc
end
local function bLc(cLc,dLc,eLc)
for fLc,gLc in pairs(cLc)do
if fLc~=dLc and(U.flat(gLc)-U.flat(eLc)).Magnitude<4.5 then
return true
end
end
return false
end
local hLc={spots=XKc(oKc.spots)}
hLc.s,hLc.kills,hLc.wave=OKc(hLc.spots)
if not hLc.s then
return bb.studyEnd(tKc,jKc,nil)
end
tKc.baseKills,tKc.baseWave=hLc.kills,hLc.wave
tKc.bestKills,tKc.bestWave=hLc.kills,hLc.wave
if sKc and sKc.aside==nil then
local iLc,jLc=XKc(hLc.spots),0
for kLc,lLc in ipairs(jKc.attackers)do
local mLc=sKc.spots[lLc.id]
local nLc=type(mLc)==upe[2059]and tonumber(mLc[1])and tonumber(mLc[3])and bb.nearSpot(lLc.spots,tonumber(mLc[1]),tonumber(mLc[3]))or nil
if nLc and nLc~=iLc[lLc.id]and not bLc(iLc,lLc.id,nLc)then
iLc[lLc.id]=nLc
jLc=jLc+1
end
end
if jLc>0 then
local oLc,pLc,qLc=OKc(iLc)
if not oLc then
return bb.studyEnd(tKc,jKc,hLc)
end
if oLc>hLc.s then
hLc={spots=iLc,s=oLc,kills=pLc,wave=qLc}
tKc.bestKills,tKc.bestWave=pLc,qLc
end
end
end
local rLc,sLc=U.now(),tKc.run
local function tLc(uLc)
if not(uLc.s and uLc.s>hLc.s+math.max(50,math.abs(hLc.s)*0.005))then
return false
end
hLc=uLc
tKc.bestKills,tKc.bestWave,tKc.better=uLc.kills,uLc.wave,(tKc.better or 0)+1
pcall(bb.bookSave,mKc,jKc,hLc,tKc)
return true
end
local function vLc()
if tKc.run-sLc>=60 or U.now()-rLc>240 then
rLc,sLc=U.now(),tKc.run
F.log(1,upe[2813],bb.studyWords(tKc))
end
end
local wLc={hLc}
for xLc,yLc in ipairs(jKc.attackers)do
local zLc={}
for ALc,BLc in ipairs(wLc)do
table.insert(zLc,BLc)
for CLc,DLc in ipairs(uKc[yLc.id]or{})do
if DLc~=BLc.spots[yLc.id]and not bLc(BLc.spots,yLc.id,DLc)then
local ELc=XKc(BLc.spots)
ELc[yLc.id]=DLc
local FLc,GLc,HLc=OKc(ELc)
if not FLc then
return bb.studyEnd(tKc,jKc,hLc)
end
local ILc={spots=ELc,s=FLc,kills=GLc,wave=HLc}
table.insert(zLc,ILc)
tLc(ILc)
vLc()
end
end
end
table.sort(zLc,function(JLc,KLc)
return(JLc.s or-1e18)>(KLc.s or-1e18)
end)
wLc={}
for LLc=1,math.min(bb.STUDY_BEAM,#zLc)do
table.insert(wLc,zLc[LLc])
end
end
local MLc={}
for NLc,OLc in ipairs(jKc.attackers)do
if uKc[OLc.id]and#uKc[OLc.id]>0 then
table.insert(MLc,OLc.id)
end
end
while lKc()and#MLc>0 do
local PLc=XKc(hLc.spots)
for QLc=1,math.min(2,#MLc)do
local RLc=MLc[math.random(#MLc)]
local SLc=uKc[RLc]
local TLc=SLc[math.random(#SLc)]
if not bLc(PLc,RLc,TLc)then
PLc[RLc]=TLc
end
end
local ULc,VLc,WLc=OKc(PLc)
if not ULc then
break
end
tLc({spots=PLc,s=ULc,kills=VLc,wave=WLc})
vLc()
end
bb.studyEnd(tKc,jKc,hLc)
end
bb.STUDY_INF_WAIT=240
function bb.validOpen(XLc,YLc)
local ZLc=N.PC.raycast(XLc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not ZLc then
return nil
end
if not N.PC.is_valid_raycast_hit(ZLc.Instance,YLc)then
return nil
end
local _Lc=ZLc.Position
if bb.blockedSpot(_Lc)then
return nil
end
local aMc=(tonumber(YLc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(aMc*2,2.5,aMc*2)
bb.probe.CFrame=CFrame.new(_Lc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return _Lc
end
