local IMc={info=bMc,team=gb.teamFrom(dMc,bMc.map),key=bb.bookKey(bMc),hard=1,scale=tonumber(bMc.rangeScale)or 1,attackers={},pauseMax=4,inf=true}
local JMc={spots={},style=upe[3000],hybridHill=bb.hybridHill and true or false}
