P.mapBook[VMc.key]={spots=YMc,style=VMc.base.style,hp=XMc.hp,n=XMc.n,kills=WMc.kills and math.floor(WMc.kills+0.5)or nil,wave=WMc.wave and math.floor(WMc.wave*10+0.5)/10 or nil,base=XMc.baseWave and math.floor(XMc.baseWave*10+0.5)/10 or nil,label=XMc.label,map=UMc.map,killScore=XMc.kills,at=os.time()}
local aNc={}
