bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3600,0.015,300
bb.HIVE_TRY_EVERY,bb.HIVE_TRIALS=3,3
function bb.layoutRecFor(CNc,DNc)
local ENc=bb.bookKey(CNc)
P.layoutRec=type(P.layoutRec)==upe[2059]and P.layoutRec or{}
local FNc=P.layoutRec[ENc]
if type(FNc)~=upe[2059]then
if not DNc then
return nil
end
FNc={at=os.time()}
P.layoutRec[ENc]=FNc
if U.count(P.layoutRec)>80 then
local GNc,HNc
for INc,JNc in pairs(P.layoutRec)do
local KNc=type(JNc)==upe[2059]and tonumber(JNc.at)or 0
if not HNc or KNc<HNc then
GNc,HNc=INc,KNc
end
end
P.layoutRec[GNc]=nil
end
end
return FNc
end
function bb.layoutAdd(LNc,MNc,NNc,ONc,PNc)
LNc.runs,LNc.wins=(tonumber(LNc.runs)or 0)+1,(tonumber(LNc.wins)or 0)+(MNc and 1 or 0)
LNc.sec,LNc.wave=type(LNc.sec)==upe[2059]and LNc.sec or{},type(LNc.wave)==upe[2059]and LNc.wave or{}
if MNc and tonumber(NNc)then
table.insert(LNc.sec,math.floor(NNc+0.5))
end
table.insert(LNc.wave,tonumber(ONc)or 0)
if tonumber(PNc)then
LNc.kills=type(LNc.kills)==upe[2059]and LNc.kills or{}
table.insert(LNc.kills,math.floor(tonumber(PNc)))
while#LNc.kills>bb.LAYOUT_KEEP do
table.remove(LNc.kills,1)
end
end
while#LNc.sec>bb.LAYOUT_KEEP do
table.remove(LNc.sec,1)
end
while#LNc.wave>bb.LAYOUT_KEEP do
table.remove(LNc.wave,1)
end
end
function bb.layoutJudge(QNc,RNc,SNc,TNc,UNc)
UNc=UNc or upe[4313]
local VNc,WNc=tonumber(QNc and QNc.runs)or 0,tonumber(RNc and RNc.runs)or 0
