end
if TNc and type(QNc.kills)==upe[2059]and type(RNc.kills)==upe[2059]and#QNc.kills>=1 and#RNc.kills>=bb.LAYOUT_CONTROL then
local XNc,YNc=bb.labMedian(QNc.kills),bb.labMedian(RNc.kills)
if XNc and YNc and XNc<YNc*0.97 and(#QNc.kills>=2 or XNc<YNc*0.85)then
