end
local ZNc,_Nc=(tonumber(QNc.wins)or 0)/VNc,(tonumber(RNc.wins)or 0)/WNc
if not SNc and _Nc>=0.5 then
if ZNc+0.25<_Nc and(VNc>=2 or(ZNc==0 and _Nc>=0.9 and WNc>=3))then
return string.format(upe[4315],tonumber(QNc.wins)or 0,VNc,VNc==1 and upe[978]or upe[1905],tonumber(RNc.wins)or 0,WNc,UNc)
end
local aOc,bOc=bb.labMedian(QNc.sec),bb.labMedian(RNc.sec)
if aOc and bOc and aOc>bOc*1.10 and(#QNc.sec>=2 or aOc>bOc*1.25)then
