function bb.layoutResult(eOc,fOc)
local gOc=bb.info
local hOc=bb.layoutSrc
if not(gOc and hOc)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
if bb.infinite and not gOc.timeLimit then
return
end
local iOc=bb.wave()
local jOc=bb.layoutRecFor(gOc,true)
jOc.at=os.time()
local kOc=gOc.timeLimit~=nil
local lOc=gOc.killScore and true or nil
local mOc=lOc and(bb.killsEnd or bb.realKills())or nil
if hOc==upe[4283]then
