end
nOc.real=type(nOc.real)==upe[2059]and nOc.real or{}
bb.layoutAdd(nOc.real,eOc,fOc,iOc,mOc)
local oOc=nOc.aside==nil and bb.layoutJudge(nOc.real,jOc.own,kOc,lOc)or nil
