local pOc=jOc.hiveUnit
bb.layoutAdd(pOc,eOc,fOc,iOc,mOc)
local qOc=bb.bookFor(gOc)
local rOc=qOc and type(qOc.real)==upe[2059]and(tonumber(qOc.real.runs)or 0)>=bb.LAYOUT_CONTROL
local sOc=rOc and qOc.real or jOc.own
local tOc=bb.layoutJudge(pOc,sOc,kOc,lOc,rOc and upe[4319]or nil)
if tOc then
pOc.aside,pOc.why=os.time(),tOc
F.log(1,upe[4219],string.format(upe[4320],tOc))
elseif(tonumber(pOc.runs)or 0)>=bb.HIVE_TRIALS then
local uOc=sOc and bb.layoutJudge(sOc,pOc,kOc,lOc,upe[4321])
if uOc and qOc and type(bb.hiveUnitPlan)==upe[2059]then
for vOc,wOc in pairs(bb.hiveUnitPlan)do
qOc.spots[vOc]=wOc
end
qOc.real={runs=pOc.runs,wins=pOc.wins,sec=pOc.sec,wave=pOc.wave,kills=pOc.kills}
qOc.hive,qOc.aside=os.time(),nil
jOc.hiveUnit=nil
F.log(1,upe[4219],string.format(upe[4322],uOc))
else
pOc.aside,pOc.why=os.time(),upe[4323]
F.log(1,upe[4219],upe[4324])
end
end
else
jOc[hOc]=type(jOc[hOc])==upe[2059]and jOc[hOc]or{}
local xOc=jOc[hOc]
bb.layoutAdd(xOc,eOc,fOc,iOc,mOc)
if hOc==upe[3651]and xOc.aside==nil then
