end
F.saveSoon()
end
bb.CONTROL_WORDS={upe[4326],upe[4327],upe[4328],upe[4329]}
function bb.controlSpot(zOc,AOc)
if not bb.killZone()then
return nil
end
local BOc=gb.holds
if not BOc(zOc.id)or V.toggleOf(zOc.id)then
return nil
end
local COc,DOc,EOc,FOc=1,0,0,{}
local GOc=bb.hurtSamples()
for HOc,IOc in ipairs(bb.mine or{})do
local JOc=IOc._stats
local KOc=JOc.id.Value
if JOc:FindFirstChild(upe[2312])and not V.isFarm(KOc)and not V.allyBuff(KOc)then
local LOc,MOc=U.flat(IOc:GetPivot().Position),JOc.range.Value
if BOc(KOc)and not V.toggleOf(KOc)then
EOc=EOc+1
table.insert(FOc,{p=LOc,r=MOc})
else
for NOc,OOc in ipairs(GOc)do
if(U.flat(OOc.pos)-LOc).Magnitude<=MOc then
COc,DOc=math.min(COc,OOc.prog),math.max(DOc,OOc.prog)
end
end
end
end
end
if DOc<=COc then
COc,DOc=0.75,0.98
end
local POc=(AOc or EOc)+1
local QOc=({COc,DOc,(COc+DOc)/2,COc-(DOc-COc)/2})[POc]
if not QOc then
return nil
end
local ROc=V.range(zOc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local SOc={}
for TOc,UOc in ipairs(bb.cands)do
local VOc,WOc,XOc=U.flat(UOc),0,0
for YOc,ZOc in ipairs(GOc)do
if(U.flat(ZOc.pos)-VOc).Magnitude<=ROc then
XOc=XOc+1
if math.abs(ZOc.prog-QOc)<=0.05 then
WOc=WOc+1
local _Oc=U.flat(ZOc.pos)
for aPc,bPc in ipairs(FOc)do
if(_Oc-bPc.p).Magnitude<=bPc.r then
WOc=WOc-0.5
break
end
end
end
end
end
if WOc>0 then
table.insert(SOc,{pos=UOc,sc=WOc,cov=XOc})
end
if TOc%60==0 then
task.wait()
end
end
table.sort(SOc,function(cPc,dPc)
return cPc.sc>dPc.sc
end)
for ePc,fPc in ipairs(SOc)do
local gPc=bb.valid(fPc.pos,zOc.data)
if gPc then
