end
end
table.insert(bb.trialTrace,string.format(upe[4347],nTc,mTc-(bb.startT or mTc),oTc,table.concat(qTc,upe[2923]),sTc,rTc+yTc,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[nTc-1]or 0,bb.teamDps or 0))
