if tgd<=0 or(tonumber(rgd.base)or 0)<=0 then
return false
end
local ugd=rgd.base/tgd
local vgd,wgd=0,0
local xgd,ygd=qgd.foes or{},rgd.foes or{}
for zgd,Agd in pairs(ygd)do
if Agd.prog>=bb.BASE_END then
vgd=vgd+Agd.hp
local Bgd=xgd[zgd]
if Bgd then
wgd=wgd+math.max(0,Bgd.hp-Agd.hp)
end
end
end
for Cgd,Dgd in pairs(xgd)do
if Dgd.prog>=bb.BASE_END and not ygd[Cgd]then
wgd=wgd+Dgd.hp
end
end
if vgd<=0 then
return false
end
local Egd=wgd/sgd
local Fgd=Egd>0 and vgd/Egd or math.huge
local Ggd={baseTime=ugd,loss=tgd,atEnd=vgd,rate=Egd,killTime=Fgd}
return ugd<bb.BASE_SOON and Fgd>ugd*bb.BASE_MARGIN,Ggd
end
